test('REQ-6-5: Merge an Eligible Pull Request - Scenario 1', async ({ page }) => {
  // GIVEN a maintainer signed in on the eligible, Open, non-draft PR
  await signIn(page, ALICE);
  await openSeededOpenPr(page);

  // the only selectable method is Create a merge commit
  await expect(page.getByText('Create a merge commit', { exact: true }).first()).toBeVisible();

  // WHEN the maintainer merges and confirms
  const merge = page.getByRole('button', { name: 'Merge pull request', exact: true });
  await expect(merge.first()).toBeEnabled();
  await merge.first().click();
  await page.getByRole('button', { name: 'Confirm merge', exact: true }).click();

  // THEN the PR displays Merged with the merger
  await expect(page.getByText('Merged', { exact: true }).first()).toBeVisible();
  await expect(page.getByText(ALICE, { exact: true }).first()).toBeVisible();

  // THEN after refreshing the PR the merged status remains
  await page.reload();
  await expect(page.getByText('Merged', { exact: true }).first()).toBeVisible();
  await expect(page.getByRole('button', { name: 'Merge pull request', exact: true })).toHaveCount(0);
});

{
  "id": "REQ-6-1#contract-1",
  "requirement": "REQ-6-1",
  "explanation": "REQ-6-1 counts only a reviewer's latest decision and states that any valid Request changes blocks merging; the merge area of a blocked PR must therefore offer no actionable merge control. Fixture: the seeded Open PR acme-docs#1 targets protected main with both toggles enabled, its current compare commit c-acme-3 carries a valid non-author approval (bob-reviewer) and test: success, and dana-dev — granted the minimal Write permission a reviewer needs — has one non-stale 'Changes requested' review on that same commit. The real merge-area renderer APP.pullSidebar derives eligibility from the approval count alone and never consults Request changes, so it emits an actionable Merge pull request button. Corrected from the failing version: the module-level escaping helper (var esc = ARC.esc) had no ARC.esc provided, so the renderer threw 'esc is not a function'; the fixture now supplies that escaping plumbing, which is external rendering plumbing, not the rule under test.",
  "functions": [
    {
      "file": "frontend/public/app.js",
      "name": "APP.pullSidebar",
      "kind": "method",
      "alias": "pullSidebar"
    }
  ],
  "initializers": [
    "frontend/public/seed.js"
  ],
  "subject": "pullSidebar",
  "setup": "window.ARC = window.ARC || {};
if (!ARC.state || !ARC.state.repos || !ARC.state.pulls) { ARC.state = JSON.parse(JSON.stringify(window.SEED || {})); }
ARC.state.ui = ARC.state.ui || {};
ARC.esc = function (s) { s = String(s == null ? '' : s); return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); };
if (typeof ARC.currentUser !== 'function') { ARC.currentUser = function () { var id = ARC.state.session; if (!id) return null; return (ARC.state.users || []).filter(function (u) { return u.id === id; })[0] || null; }; }
ARC.state.session = 'u-alice';
ARC.state.grants = ARC.state.grants || [];
ARC.state.reviews = ARC.state.reviews || [];
ARC.state.checks = ARC.state.checks || [];
ARC.state.grants.push({ id: 'g-probe-dana', repo: 'r-acme-docs', subjectType: 'user', subject: 'u-dana', role: 'Write', created: '2024-03-02T10:00:00Z' });
ARC.state.reviews.push({ id: 'rv-probe-dana', pr: 'p-1', reviewer: 'u-dana', commit: 'c-acme-3', state: 'Changes requested', summary: 'Please rework the search flow.', time: '2024-03-02T12:00:00Z', stale: false });
ARC.state.checks = ARC.state.checks.filter(function (c) { return !(c.pr === 'p-1' && c.commit === 'c-acme-3'); });
ARC.state.checks.push({ id: 'ck-probe', pr: 'p-1', commit: 'c-acme-3', status: 'success', setter: 'u-alice', time: '2024-03-02T13:00:00Z' });",
  "precondition": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p-1'; })[0];
assert(repo && pr, 'seeded repository acme-docs and pull request p-1 exist');
assert(pr.status === 'open' && pr.base === 'main' && pr.compareCommit === 'c-acme-3', 'p-1 is Open, targets main and its current compare commit is c-acme-3');
var prot = ARC.state.protections.filter(function (p) { return p.repo === repo.id && p.branch === 'main'; })[0];
assert(prot && prot.approval === true && prot.check === true, 'main is protected with Require 1 approval and Require status check test');
var ck = ARC.state.checks.filter(function (c) { return c.pr === pr.id && c.commit === pr.compareCommit; })[0];
assert(ck && ck.status === 'success', 'the required test check of the current compare commit is success');
var approvals = ARC.state.reviews.filter(function (r) { return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Approved' && r.reviewer !== pr.author; });
assert(approvals.length === 1, 'exactly one valid non-author approval exists for the current compare commit');
var blocking = ARC.state.reviews.filter(function (r) { return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Changes requested'; });
assert(blocking.length === 1, 'exactly one valid non-stale Request changes review exists for the current compare commit');
assert(APP.canAdmin(repo, ARC.currentUser()) === true, 'the signed-in organisation Owner holds repository Admin permission and may merge');",
  "check": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p-1'; })[0];
var html = pullSidebar.call(APP, repo, pr);
assert(typeof html === 'string' && html.length > 0, 'the pull request merge sidebar renders');
assert(html.indexOf('Merge pull request') >= 0, 'a merge control is present in the sidebar (control: the merge area is rendered for this permitted merger)');
assert(!/data-action="merge-pr"/.test(html), 'a valid Request changes review on the current compare commit blocks merging, so no actionable Merge pull request control may be offered');"
}

{
  "id": "REQ-6-5#contract-1",
  "requirement": "REQ-6-5",
  "explanation": "REQ-6-5 requires that on a protected target each enabled rule is enforced independently, so an Open PR with a valid non-author approval but a `test` check that is not success stays blocked and shows a disabled Merge pull request button plus the unmet-condition explanation. Fixture: seeded PR acme-docs#1 targets protected main with both Require 1 approval and Require status check test enabled; bob-reviewer's approval is valid and non-stale for the current compare commit c-acme-3, no valid Request changes exists, and the check record for that same commit is 'pending'. APP.pullSidebar (the real merge-area renderer) computes ok from pr.status and the approval rule only and never reads the check rule, so it renders an actionable Merge pull request control for a PR that the protection rule requires to be blocked. Corrected from the failing version: ARC.esc (the external escaping plumbing consumed by the module-level esc helper) is now supplied in setup so the renderer can run.",
  "functions": [
    {
      "file": "frontend/public/app.js",
      "name": "APP.pullSidebar",
      "kind": "method",
      "alias": "pullSidebar"
    }
  ],
  "initializers": [
    "frontend/public/seed.js"
  ],
  "subject": "pullSidebar",
  "setup": "window.ARC = window.ARC || {};
if (!ARC.state || !ARC.state.repos || !ARC.state.pulls) { ARC.state = JSON.parse(JSON.stringify(window.SEED || {})); }
ARC.state.ui = ARC.state.ui || {};
ARC.esc = function (s) { s = String(s == null ? '' : s); return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); };
if (typeof ARC.currentUser !== 'function') { ARC.currentUser = function () { var id = ARC.state.session; if (!id) return null; return (ARC.state.users || []).filter(function (u) { return u.id === id; })[0] || null; }; }
ARC.state.session = 'u-alice';
ARC.state.checks = ARC.state.checks || [];
if (!ARC.state.checks.some(function (c) { return c.pr === 'p-1' && c.commit === 'c-acme-3'; })) { ARC.state.checks.push({ id: 'ck-1', pr: 'p-1', commit: 'c-acme-3', status: 'pending', setter: null, time: null }); }",
  "precondition": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p-1'; })[0];
assert(repo && pr, 'seeded repository acme-docs and pull request p-1 exist');
assert(pr.status === 'open' && pr.base === 'main' && pr.compareCommit === 'c-acme-3', 'p-1 is Open, targets main and its current compare commit is c-acme-3');
var prot = ARC.state.protections.filter(function (p) { return p.repo === repo.id && p.branch === 'main'; })[0];
assert(prot && prot.approval === true && prot.check === true, 'main is protected with Require 1 approval and Require status check test');
var ck = ARC.state.checks.filter(function (c) { return c.pr === pr.id && c.commit === pr.compareCommit; })[0];
assert(ck && ck.status === 'pending', 'the required test check of the current compare commit is pending, not success');
var approvals = ARC.state.reviews.filter(function (r) { return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Approved' && r.reviewer !== pr.author; });
assert(approvals.length === 1, 'exactly one valid non-author approval exists for the current compare commit');
var blocking = ARC.state.reviews.filter(function (r) { return r.pr === pr.id && r.commit === pr.compareCommit && !r.stale && r.state === 'Changes requested'; });
assert(blocking.length === 0, 'no valid Request changes review exists, so only the status-check rule is unmet');
assert(APP.canAdmin(repo, ARC.currentUser()) === true, 'the signed-in organisation Owner holds repository Admin permission and may merge');",
  "check": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p-1'; })[0];
var html = pullSidebar.call(APP, repo, pr);
assert(typeof html === 'string' && html.length > 0, 'the pull request merge sidebar renders');
assert(html.indexOf('Merge pull request') >= 0, 'a merge control is present in the sidebar (control: the merge area is rendered for this permitted merger)');
assert(!/data-action="merge-pr"/.test(html), 'with Require status check test enabled and test not success, the merge control must be non-actionable (disabled) rather than enabled');"
}

{
  "id": "REQ-6-3-3#contract-1",
  "requirement": "REQ-6-3-3",
  "explanation": "REQ-6-3-3 requires that a draft started with Start a review stays pending: it is shown with 'Pending review' to its author but is not made public before review submission. Fixture: the seeded Open PR acme-docs#1 is viewed by alice-dev (its author, a different account from the commenter bob-reviewer) and the Files changed store holds one already-published inline comment plus one unsubmitted (published:false) inline comment by bob-reviewer on the same current compare commit c-acme-3. APP.pullFiles, the real Files-changed renderer, lists every inline record of the PR without any author or publication check, so bob-reviewer's unsubmitted draft body is rendered to alice-dev and thus becomes public before submission. Corrected from the failing version: ARC.esc (the external escaping helper consumed by the module-level esc binding) is supplied in setup, and the fixture explicitly clears ui().lineEditor so the diff-line rendering path used here runs.",
  "functions": [
    {
      "file": "frontend/public/app.js",
      "name": "APP.pullFiles",
      "kind": "method",
      "alias": "pullFiles"
    }
  ],
  "initializers": [
    "frontend/public/seed.js"
  ],
  "subject": "pullFiles",
  "setup": "window.ARC = window.ARC || {};
if (!ARC.state || !ARC.state.repos || !ARC.state.pulls) { ARC.state = JSON.parse(JSON.stringify(window.SEED || {})); }
ARC.state.ui = ARC.state.ui || {};
ARC.state.ui.lineEditor = null;
ARC.esc = function (s) { s = String(s == null ? '' : s); return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); };
if (typeof ARC.currentUser !== 'function') { ARC.currentUser = function () { var id = ARC.state.session; if (!id) return null; return (ARC.state.users || []).filter(function (u) { return u.id === id; })[0] || null; }; }
ARC.state.session = 'u-alice';
ARC.state.inline = [
  { id: 'ic-probe-published', pr: 'p-1', path: 'src/search.ts', commit: 'c-acme-3', line: 1, author: 'u-bob', body: 'Published review note', published: true, created: '2024-03-02T11:00:00Z' },
  { id: 'ic-probe-pending', pr: 'p-1', path: 'src/search.ts', commit: 'c-acme-3', line: 2, author: 'u-bob', body: 'Unsubmitted draft note', published: false, created: '2024-03-02T12:00:00Z' }
];",
  "precondition": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p-1'; })[0];
assert(repo && pr, 'seeded repository acme-docs and pull request p-1 exist');
assert(pr.status === 'open' && pr.author === 'u-alice', 'p-1 is Open and authored by alice-dev, the signed-in account');
assert(ARC.currentUser().id === pr.author, 'the signed-in account is the pull-request author');
var bob = ARC.state.users.filter(function (u) { return u.username === 'bob-reviewer'; })[0];
assert(bob && bob.id !== pr.author, 'bob-reviewer is a different account from the pull-request author');
var pending = ARC.state.inline.filter(function (c) { return c.pr === pr.id && c.published === false && c.author === bob.id; });
assert(pending.length === 1 && pending[0].body === 'Unsubmitted draft note', 'bob-reviewer has exactly one unsubmitted pending review draft');
var submitted = ARC.state.inline.filter(function (c) { return c.pr === pr.id && c.published === true; });
assert(submitted.length === 1, 'one submitted inline comment exists as a control');
assert(!ARC.state.ui.lineEditor, 'no line editor is open');",
  "check": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p-1'; })[0];
var html = pullFiles.call(APP, repo, pr);
assert(typeof html === 'string' && html.length > 0, 'the Files changed view renders');
assert(html.indexOf('Published review note') >= 0, 'a submitted inline comment stays visible in the diff view (control)');
assert(html.indexOf('Unsubmitted draft note') < 0, 'an unsubmitted pending review draft must not be public to another account before review submission');"
}

{
  "id": "REQ-5-3-1#contract-1",
  "requirement": "REQ-5-3-1",
  "explanation": "REQ-5-3-1 defines assignable members as accounts holding at least Triage permission on the current repository and states that non-assignable users do not appear in the results. In the seed, carol-reader is an organization member of acme-demo but holds only a direct Read grant on acme-docs (her only team is frontend-child, which has no grant and team hierarchy is not transitive), so the application's own predicate APP.canTriage(repo, carol-reader) is false, while bob-reviewer (direct Write) and the signed-in Owner are eligible. The picker renderer that the issue detail page is meant to show filters candidates by organization membership instead of repository permission, so it offers carol-reader as an assignable option. Corrected from the rejected version: the picker is declared inside the actions object, so it must be selected by its full declaration path APP.actions.assigneePicker (the runner reported APP.assigneePicker does not exist); ARC.esc and the ARC.route resolution used by the picker are supplied as external plumbing.",
  "functions": [
    {
      "file": "frontend/public/app.js",
      "name": "APP.actions.assigneePicker",
      "kind": "method",
      "alias": "assigneePicker"
    }
  ],
  "initializers": [
    "frontend/public/seed.js"
  ],
  "subject": "assigneePicker",
  "setup": "window.ARC = window.ARC || {};\nif (!ARC.state || !ARC.state.repos || !ARC.state.issues) { ARC.state = JSON.parse(JSON.stringify(window.SEED || {})); }\nARC.state.ui = ARC.state.ui || {};\nARC.state.ui.assigneeQuery = '';\nARC.esc = function (s) { s = String(s == null ? '' : s); return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;'); };\nif (typeof ARC.currentUser !== 'function') { ARC.currentUser = function () { var id = ARC.state.session; if (!id) return null; return (ARC.state.users || []).filter(function (u) { return u.id === id; })[0] || null; }; }\nARC.state.session = 'u-alice';\nARC.route = function () { return { name: 'repos', params: ['acme-demo', 'acme-docs', 'issues', '1'] }; };",
  "precondition": "var repo = ARC.state.repos.filter(function (r) { return r.id === 'r-acme-docs'; })[0];\nvar issue = ARC.state.issues.filter(function (i) { return i.repo === repo.id && i.number === 1; })[0];\nvar carol = ARC.state.users.filter(function (u) { return u.username === 'carol-reader'; })[0];\nvar bob = ARC.state.users.filter(function (u) { return u.username === 'bob-reviewer'; })[0];\nassert(repo && issue && carol && bob, 'seeded repository acme-docs, issue 1 and both accounts exist');\nassert(issue.status === 'open', 'issue 1 can be assigned participants');\nassert(ARC.state.memberships.some(function (m) { return m.org === repo.owner && m.user === carol.id; }), 'carol-reader is an organization member, so membership alone would include her');\nassert(APP.canTriage(repo, carol) === false, 'carol-reader is below Triage (Read) on the repository and is therefore not assignable');\nassert(APP.canTriage(repo, bob) === true, 'bob-reviewer is Triage-or-higher (Write) on the repository and is assignable');\nassert(APP.canTriage(repo, ARC.currentUser()) === true, 'the signed-in organization Owner may assign participants');",
  "check": "var html = assigneePicker.call(APP);\nassert(typeof html === 'string' && html.indexOf('role=\"option\"') >= 0, 'the assignee picker renders selectable member options');\nassert(html.indexOf('bob-reviewer') >= 0, 'eligible bob-reviewer is offered as an assignable control');\nassert(html.indexOf('carol-reader') < 0, 'carol-reader holds only Read permission on the repository and must not appear in assignee results');"
}
